-- PT121-S4-Q24. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT121-S4-Q24$batch03$ AND q.stimulus=$batch03$Many Seychelles warblers of breeding age forgo breeding, remaining instead with their parents and helping to raise their own siblings. This behavior, called cooperative breeding, results from the scarcity of nesting territory for the birds on the tiny island that, until recently, was home to the world’s population of Seychelles warblers. Yet when healthy warblers were transplanted to a much larger neighboring island as part of an experiment, most of those warblers maintained a pattern of cooperative breeding.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to explain the result of the experiment?$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT121-S4-Q24'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT121-S4-Q24$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT121-S4-Q24'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT121-S4-Q24$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Cooperative breeding comes from a shortage of nesting territory on the tiny home island.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Warblers moved to a much larger island still bred cooperatively?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$"Larger island" does not have to mean "more nesting territory." If most of the new island is not the kind of land warblers nest in, territory could still be scarce, and the same cause would produce the same behavior.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find that nesting territory on the new island was still scarce.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT121-S4-Q24$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$However many of the birds were too young to breed, the stimulus says *most* of the transplanted warblers kept the cooperative pattern. Young birds do not explain what the majority did.$batch03$), ($batch03$B$batch03$, $batch03$Climate is not the cause the stimulus gives for cooperative breeding. A similar climate does not explain the result.$batch03$), ($batch03$C$batch03$, $batch03$Most of the new island's land is not suitable for nesting. Usable territory may be just as scarce as at home, so the same cause keeps the birds breeding cooperatively.$batch03$), ($batch03$D$batch03$, $batch03$Other species' reasons for cooperative breeding do not explain these warblers' behavior.$batch03$), ($batch03$E$batch03$, $batch03$Fewer competitors for nesting territory should make it *easier* to breed alone, which deepens the puzzle.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT121-S4-Q24$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
